		var source = Encoding.ASCII.GetBytes( String.Concat( "(*ANY)(?im)^", String.Concat( Enumerable.Repeat( "()", 256 ) ), "(*MARK:K)[I-K]A" ) );
		var subject = Convert.FromHexString( hex );
		var reference = Reference( source, policy, 15 );
		AssertLiteral( reference, subject, 1, "", "" );
		AssertLiteral( reference, subject, 3, String.Concat( spans, ",", String.Join( ",", Enumerable.Repeat( "3:0", 256 ) ) ), "4B" );
		var compiled = Compile( source, Options( policy, 15 ) );
		Compare( reference, subject, 1, compiled.Match( subject, 1 ), "full capture split" );
		Compare( reference, subject, 3, compiled.Match( subject, 3 ), "full capture boundary" );
	}

	[Fact]
	public void BoundedMarkPrefixesRetainNativeBoundaryResults() {
		var sources = new[] { 900, 1100 }.Select( count => Encoding.ASCII.GetBytes( String.Concat( "(*ANY)(?im)^", String.Concat( Enumerable.Repeat( "(*MARK:K)", count ) ), "[I-K]A" ) ) ).ToArray();
		var references = sources.Select( source => Reference( source, 0, 15 ) ).ToArray();
		var subject = "\u2028IA"u8.ToArray();
		foreach ( var reference in references ) { AssertLiteral( reference, subject, 3, "3:2", "4B" ); }
		AssertLiteral( references[0], subject, 1, "", "" );
		var compiled = sources.Select( source => Compile( source, Options( 0, 15 ) ) ).ToArray();
		Compare( references[0], subject, 1, compiled[0].Match( subject, 1 ), "bounded marked-set split" );
		for ( var index = 0; index < compiled.Length; index++ ) {
			Compare( references[index], subject, 3, compiled[index].Match( subject, 3 ), "valid boundary including proof fallback" );
		}
	}

	[Fact]
	public void CallerAndPrefixMarkedSetsRetainSharedWorkAndCancellation() {
		var body = "(*ANY)(?im)^(*MARK:K)[I-K]A";
		var sources = new[] { Encoding.ASCII.GetBytes( body ), Encoding.ASCII.GetBytes( String.Concat( "(*TURKISH_CASING)", body ) ) };
		var references = new[] { Reference( sources[0], 2, 15 ), Reference( sources[1], 0, 15 ) };
		var subject = "\u2028ıA"u8.ToArray();
		foreach ( var reference in references ) { AssertLiteral( reference, subject, 1, "", "" ); AssertLiteral( reference, subject, 3, "3:3", "4B" ); }
		var callerSteps = new List<int>();
		var prefixSteps = new List<int>();
		var options = Options( 2, 15 ) with { WorkObserver = callerSteps.Add };
		var caller = Compile( sources[0], options );
		var prefix = Compile( sources[1], Options( 0, 15 ) with { WorkObserver = prefixSteps.Add } );
		Compare( references[0], subject, 1, caller.Match( subject, 1 ), "caller marked-set split" );
		Compare( references[1], subject, 1, prefix.Match( subject, 1 ), "prefix marked-set split" );
		Assert.Equal( prefixSteps, callerSteps );
		callerSteps.Clear(); prefixSteps.Clear();
		Compare( references[0], subject, 3, caller.Match( subject, 3 ), "caller marked-set work" );
		Compare( references[1], subject, 3, prefix.Match( subject, 3 ), "prefix marked-set work" );
		Assert.Equal( prefixSteps, callerSteps );
		Assert.Equal( Enumerable.Range( 1, callerSteps.Count ), callerSteps );
		Assert.True( callerSteps.Count > 2 );
		var limited = Compile( sources[0], options with { MatchWorkLimit = callerSteps.Count - 1 } ).Match( subject, 3 );
		Assert.Equal( PcreByteDiagnosticCode.MatchWorkLimitExceeded, limited.Diagnostic?.Code );
		Assert.Null( limited.Match );
		using var cancellation = new CancellationTokenSource();
		var canceled = Compile( sources[0], options with { WorkObserver = count => { if ( count == 2 ) { cancellation.Cancel(); } } } );
		Assert.Throws<OperationCanceledException>( () => canceled.Match( subject, 3, cancellation.Token ) );
		Assert.Throws<OperationCanceledException>( () => PcreByteCompiler.Compile( sources[0], options, cancellation.Token ) );
	}

	private static PcreByteOptions Options( int policy, int mode ) => new() {
		Utf8 = ( mode & 1 ) != 0, Ucp = ( mode & 2 ) != 0, MatchInvalidUtf = ( mode & 4 ) != 0, Caseless = ( mode & 8 ) != 0,
		CaselessRestricted = ( policy & 1 ) != 0, TurkishCasing = ( policy & 2 ) != 0
	};
	private static PcreRegex8Bit Reference( byte[] source, int policy, int mode ) => new(
		source, Encoding.UTF8, new PcreRegexSettings {
			Options = PcreOptions.Compiled | (PcreOptions)( ( ( mode & 1 ) != 0 ? 0x80000u : 0u ) | ( ( mode & 2 ) != 0 ? 0x20000u : 0u )
				| ( ( mode & 4 ) != 0 ? 0x4000000u : 0u ) | ( ( mode & 8 ) != 0 ? 8u : 0u ) ),
			ExtraCompileOptions = (PcreExtraCompileOptions)( ( ( policy & 1 ) != 0 ? 0x80 : 0 ) | ( ( policy & 2 ) != 0 ? 0x10000 : 0 ) ), ParensLimit = 512
		} );
	private static PcreCompiledBytePattern Compile( byte[] source, PcreByteOptions options ) {
		var actual = PcreByteCompiler.Compile( source, options );
		Assert.True( actual.IsSuccess, $"{Encoding.UTF8.GetString( source )}: {actual.Diagnostic?.Message}" );
		return Assert.IsType<PcreCompiledBytePattern>( actual.Pattern );
	}
	private static void AssertLiteral( PcreRegex8Bit reference, byte[] subject, int offset, string spans, string mark ) {
		var match = reference.Match( subject, offset );
		Assert.Equal( spans.Length > 0, match.Success );
		if ( !match.Success ) { return; }
		Assert.Equal( mark, Convert.ToHexString( match.Mark.ToArray() ) );
		var groups = spans.Split( ',' );
		Assert.Equal( groups.Length, match.Groups.Count );
		for ( var group = 0; group < groups.Length; group++ ) {
			var capture = match.Groups[group];
			Assert.Equal( groups[group], capture.Success ? $"{capture.Index}:{capture.Length}" : "-" );
		}
	}
	private static void Compare( PcreRegex8Bit reference, byte[] subject, int offset, PcreByteMatchResult actual, string context ) {
		var expected = reference.Match( subject, offset );
		Assert.True( actual.IsSuccess, $"{context}: {actual.Diagnostic?.Message}" );
		Assert.Equal( expected.Success ? expected.Index : -1, actual.Match?.ByteIndex ?? -1 );
		if ( !expected.Success ) { return; }
		Assert.Equal( expected.Length, actual.Match!.ByteLength );
		Assert.Equal( expected.Mark.ToArray(), actual.Match.MarkName.ToArray() );
		Assert.Equal( expected.Groups.Count, actual.Match.Captures.Count );
		for ( var group = 0; group < expected.Groups.Count; group++ ) {
			var capture = expected.Groups[group];
			Assert.Equal( capture.Success ? new PcreByteCapture( capture.Index, capture.Length ) : null, actual.Match.Captures[group] );
		}
	}
}
